// Generated by `marko-ui add` from components.json `iconLibrary`: "lucide".
// Only that library's icon map is imported, so it is the only one bundled.
// To switch libraries, change `iconLibrary` and re-run `marko-ui add icon --overwrite`.
import { lucideIcons } from "./__lucide__.ts";
import type { IconLibraryName } from "./icon-names.ts";
import { FALLBACK_INNER, withSuffixFallback } from "./render.ts";

// This project renders every icon from "lucide" regardless of the
// `library` prop.
export { resolveIconLibrary } from "./resolve-library.ts";

export function resolveIconInner(name: string, _library?: IconLibraryName): string {
  return withSuffixFallback(lucideIcons, name) ?? FALLBACK_INNER;
}
